def schedule_next_checked_day(start_date_obj, doc, starts_from_time, day_field_map):
    """Find the next checked day within 7 days, respecting expire_on"""
    if not start_date_obj or not doc or not starts_from_time or not day_field_map:
        return

    found = False
    for i in range(1, 8):
        try:
            next_date = frappe.utils.add_to_date(start_date_obj, days=i)
            if not next_date:
                continue

            next_day_index = next_date.weekday()
            next_checkbox = day_field_map.get(next_day_index)

            if next_checkbox and doc.get(next_checkbox):
                next_date_str = frappe.utils.formatdate(next_date, "yyyy-mm-dd")
                if next_date_str:
                    future_alert_str = next_date_str + " " + starts_from_time

                    # Respect expire_on
                    if doc.expire_on:
                        expire_datetime = frappe.utils.get_datetime(str(doc.expire_on) + " 23:59:59")
                        if frappe.utils.get_datetime(future_alert_str) > expire_datetime:
                            doc.next_alert_on = None
                            doc.enabled = 0
                        else:
                            doc.next_alert_on = future_alert_str
                    else:
                        doc.next_alert_on = future_alert_str

                    found = True
                    break
        except Exception:
            continue

    if not found:
        doc.next_alert_on = None


# Main logic
now = frappe.utils.now_datetime()
docs = frappe.get_all(
    "iWEXClock Reminder",
    filters={"next_alert_on": ("<", now), "enabled": 1},
    fields=[
        "name", "next_alert_on", "previous_alert_was", "frequency", "start_date",
        "from_time", "to_time", "start_time", "mon", "tue", "wed", "thu", "fri",
        "sat", "sun", "duration", "every", "expire_on"
    ]
)

for d in docs:
    try:
        if not d.next_alert_on:
            continue

        # Update previous_alert_was
        frappe.db.set_value("iWEXClock Reminder", d.name, "previous_alert_was", d.next_alert_on)

        # Prepare expire_on datetime
        expire_datetime = frappe.utils.get_datetime(str(d.expire_on) + " 23:59:59") if d.expire_on else None

        if d.frequency == "Once":
            frappe.db.set_value("iWEXClock Reminder", d.name, "next_alert_on", None)
            frappe.db.set_value("iWEXClock Reminder", d.name, "enabled", 0)

        elif d.frequency in ["Daily", "Weekly", "Monthly", "Annually"]:
            new_next_alert = frappe.utils.get_datetime(d.next_alert_on)
            while new_next_alert <= now:
                if d.frequency == "Daily":
                    new_next_alert = frappe.utils.add_days(new_next_alert, 1)
                elif d.frequency == "Weekly":
                    new_next_alert = frappe.utils.add_days(new_next_alert, 7)
                elif d.frequency == "Monthly":
                    new_next_alert = frappe.utils.add_months(new_next_alert, 1)
                elif d.frequency == "Annually":
                    new_next_alert = frappe.utils.add_years(new_next_alert, 1)

                # Respect expire_on
                if expire_datetime and new_next_alert > expire_datetime:
                    new_next_alert = None
                    frappe.db.set_value("iWEXClock Reminder", d.name, "enabled", 0)
                    break

            frappe.db.set_value("iWEXClock Reminder", d.name, "next_alert_on", new_next_alert)

        elif d.frequency == "Custom":
            try:
                start_date_obj = frappe.utils.get_datetime(d.start_date) if d.start_date else None
                if start_date_obj:
                    today_obj = frappe.utils.get_datetime(frappe.utils.today())
                    current_date_obj = today_obj if start_date_obj.date() < today_obj.date() else start_date_obj

                    day_field_map = {0: "mon", 1: "tue", 2: "wed", 3: "thu", 4: "fri", 5: "sat", 6: "sun"}
                    checkbox_field = day_field_map.get(current_date_obj.weekday())

                    starts_from_time = str(d.from_time) if d.from_time else "00:00:00"
                    ends_at_time = str(d.to_time) if d.to_time else "23:59:59"
                    start_time = str(d.start_time) if d.start_time else "00:00:00"

                    if checkbox_field and d.get(checkbox_field):
                        interval = 60
                        if d.duration and d.every:
                            if d.duration == 'Seconds':
                                interval = int(d.every)
                            elif d.duration == 'Minutes':
                                interval = int(d.every) * 60
                            elif d.duration == 'Hours':
                                interval = int(d.every) * 3600

                        # Generate alert times
                        alert_times = []
                        current_time = frappe.utils.get_time(starts_from_time)
                        end_time_obj = frappe.utils.get_time(ends_at_time)
                        start_time_obj = frappe.utils.get_time(start_time)

                        while current_time and end_time_obj and current_time <= end_time_obj:
                            if current_time >= start_time_obj:
                                alert_times.append(current_time)

                            total_seconds = current_time.hour * 3600 + current_time.minute * 60 + current_time.second + interval
                            hours = (total_seconds // 3600) % 24
                            minutes = (total_seconds % 3600) // 60
                            seconds = total_seconds % 60
                            time_str = "%02d:%02d:%02d" % (hours, minutes, seconds)
                            current_time = frappe.utils.get_time(time_str)

                        # Pick next future alert respecting expire_on
                        next_alert_time = None
                        for time_obj in alert_times:
                            alert_datetime = frappe.utils.get_datetime(frappe.utils.formatdate(current_date_obj, "yyyy-mm-dd") + " " + str(time_obj))
                            if alert_datetime > now and (not expire_datetime or alert_datetime <= expire_datetime):
                                next_alert_time = alert_datetime
                                break

                        if next_alert_time:
                            frappe.db.set_value("iWEXClock Reminder", d.name, "next_alert_on", next_alert_time)
                        else:
                            doc = frappe.get_doc("iWEXClock Reminder", d.name)
                            schedule_next_checked_day(current_date_obj, doc, starts_from_time, day_field_map)
                            # respect expire_on
                            if doc.next_alert_on and expire_datetime and frappe.utils.get_datetime(doc.next_alert_on) > expire_datetime:
                                doc.next_alert_on = None
                                doc.enabled = 0
                            frappe.db.set_value("iWEXClock Reminder", d.name, "next_alert_on", doc.next_alert_on)
                            frappe.db.set_value("iWEXClock Reminder", d.name, "enabled", doc.enabled)
                    else:
                        # Current day not checked → schedule next checked day
                        doc = frappe.get_doc("iWEXClock Reminder", d.name)
                        schedule_next_checked_day(current_date_obj, doc, starts_from_time, day_field_map)
                        if doc.next_alert_on and expire_datetime and frappe.utils.get_datetime(doc.next_alert_on) > expire_datetime:
                            doc.next_alert_on = None
                            doc.enabled = 0
                        frappe.db.set_value("iWEXClock Reminder", d.name, "next_alert_on", doc.next_alert_on)
                else:
                    frappe.db.set_value("iWEXClock Reminder", d.name, "next_alert_on", None)
            except Exception as e:
                frappe.log_error(f"Error in Custom frequency for {d.name}: {str(e)}", "update_previous_alerts")
                frappe.db.set_value("iWEXClock Reminder", d.name, "next_alert_on", None)

    except Exception as e:
        frappe.log_error(f"update_previous_alerts failed for {d.name}: {str(e)}", "update_previous_alerts")

# Commit once for all
frappe.db.commit()

